// Shared 3D-look shading helpers for arcade games. Single light source:
// upper-left. Colours come from the caller's palette only (base colours are
// lightened/darkened, never replaced). No engine or mechanic code lives here.
import 'package:flutter/material.dart';

/// Lighten (f > 0, towards white) or darken (f < 0, towards black).
Color shadeColor(Color base, double f) => f >= 0
    ? Color.lerp(base, Colors.white, f)!
    : Color.lerp(base, Colors.black, -f)!;

Paint _spherePaint(Rect bounds, Color base) => Paint()
  ..shader = RadialGradient(
    center: const Alignment(-0.4, -0.4),
    radius: 1.25,
    colors: [shadeColor(base, 0.55), base, shadeColor(base, -0.45)],
    stops: const [0.0, 0.55, 1.0],
  ).createShader(bounds);

void _specular(Canvas cv, Offset center, double r) {
  cv.drawOval(
      Rect.fromCenter(
          center: center + Offset(-r * 0.35, -r * 0.38),
          width: r * 0.55,
          height: r * 0.34),
      Paint()..color = Colors.white.withOpacity(0.75));
  cv.drawCircle(center + Offset(-r * 0.42, -r * 0.45), r * 0.10,
      Paint()..color = Colors.white.withOpacity(0.9));
}

/// Glossy ball / bumper / target: cast shadow + radial sphere + highlight.
/// Same centre and radius as the flat circle it replaces.
void paintShadedCircle(Canvas cv, Offset center, double r, Color base) {
  cv.drawCircle(center + Offset(r * 0.12, r * 0.18), r,
      Paint()..color = Colors.black.withOpacity(0.30));
  cv.drawCircle(center, r, _spherePaint(Rect.fromCircle(center: center, radius: r), base));
  _specular(cv, center, r);
}

/// Glossy oval (player-badge blob shape): same rect as the flat oval.
void paintShadedOval(Canvas cv, Rect rect, Color base) {
  final c = rect.center;
  final r = rect.width / 2;
  cv.drawOval(rect.translate(2, 3), Paint()..color = Colors.black.withOpacity(0.30));
  cv.drawOval(rect, _spherePaint(rect, base));
  _specular(cv, c, r * 0.8);
}

/// Shaded filled path (star / diamond badges): shadow + gradient + dot.
void paintShadedPath(Canvas cv, Path path, Rect bounds, Color base) {
  cv.drawPath(path.shift(const Offset(2, 3)),
      Paint()..color = Colors.black.withOpacity(0.30));
  cv.drawPath(path, _spherePaint(bounds, base));
  cv.drawCircle(
      Offset(bounds.left + bounds.width * 0.32, bounds.top + bounds.height * 0.26),
      bounds.width * 0.06,
      Paint()..color = Colors.white.withOpacity(0.75));
}

/// Beveled rectangle: cast shadow + vertical (or horizontal, for walls)
/// gradient + a light top/left edge + a dark bottom/right edge.
/// Same rect and corner radius as the flat rect it replaces.
void paintBeveledRect(Canvas cv, Rect rect, double radius, Color base,
    {Axis direction = Axis.vertical}) {
  final rr = RRect.fromRectAndRadius(rect, Radius.circular(radius));
  cv.drawRRect(rr.shift(const Offset(0, 3)),
      Paint()..color = Colors.black.withOpacity(0.30));
  final grad = direction == Axis.vertical
      ? LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [shadeColor(base, 0.35), base, shadeColor(base, -0.35)])
      : LinearGradient(
          begin: Alignment.centerLeft,
          end: Alignment.centerRight,
          colors: [shadeColor(base, 0.35), base, shadeColor(base, -0.35)]);
  cv.drawRRect(rr, Paint()..shader = grad.createShader(rect));
  if (direction == Axis.vertical) {
    cv.drawLine(Offset(rect.left + radius, rect.top + 2),
        Offset(rect.right - radius, rect.top + 2),
        Paint()..color = Colors.white.withOpacity(0.35)..strokeWidth = 2);
    cv.drawLine(Offset(rect.left + radius, rect.bottom - 2),
        Offset(rect.right - radius, rect.bottom - 2),
        Paint()..color = Colors.black.withOpacity(0.30)..strokeWidth = 2);
  } else {
    cv.drawLine(Offset(rect.left + 2, rect.top + radius),
        Offset(rect.left + 2, rect.bottom - radius),
        Paint()..color = Colors.white.withOpacity(0.35)..strokeWidth = 2);
    cv.drawLine(Offset(rect.right - 2, rect.top + radius),
        Offset(rect.right - 2, rect.bottom - radius),
        Paint()..color = Colors.black.withOpacity(0.30)..strokeWidth = 2);
  }
}

/// Shaded stroke (flippers, rhythm hit line): glow under-stroke + main
/// stroke + thin upper highlight. Same endpoints and width as before.
void paintShadedLine(
    Canvas cv, Offset a, Offset b, Color base, double width) {
  final shadow = Paint()
    ..color = Colors.black.withOpacity(0.30)
    ..strokeWidth = width
    ..strokeCap = StrokeCap.round;
  cv.drawLine(a + const Offset(1.5, 2), b + const Offset(1.5, 2), shadow);
  cv.drawLine(a, b,
      Paint()..color = base..strokeWidth = width..strokeCap = StrokeCap.round);
  cv.drawLine(a + const Offset(-1, -1), b + const Offset(-1, -1),
      Paint()..color = Colors.white.withOpacity(0.30)..strokeWidth = width * 0.35..strokeCap = StrokeCap.round);
}

/// Shaded arc stroke (spin rings): soft glow + main stroke + highlight.
void paintShadedArc(Canvas cv, Rect rect, double start, double sweep,
    Color base, double width) {
  cv.drawArc(rect, start, sweep, false,
      Paint()..color = base.withOpacity(0.18)..style = PaintingStyle.stroke..strokeWidth = width + 8);
  cv.drawArc(rect, start, sweep, false,
      Paint()..color = base..style = PaintingStyle.stroke..strokeWidth = width);
  cv.drawArc(rect, start, sweep, false,
      Paint()..color = Colors.white.withOpacity(0.30)..style = PaintingStyle.stroke..strokeWidth = 2);
}

/// Layered-depth play-area background. Paint FIRST in the painter, before
/// any object: dark far layer, mid radial glow, foreground vignette.
void paintDepthBackground(Canvas cv, Size size, Color dark, Color primary) {
  final full = Offset.zero & size;
  cv.drawRect(
      full,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [dark, shadeColor(dark, 0.15), shadeColor(primary, -0.55)],
        ).createShader(full));
  cv.drawRect(
      full,
      Paint()
        ..shader = RadialGradient(
          center: const Alignment(-0.6, -0.7),
          radius: 1.2,
          colors: [primary.withOpacity(0.28), Colors.transparent],
        ).createShader(full));
  cv.drawRect(
      full,
      Paint()
        ..shader = const RadialGradient(
          center: Alignment.center,
          radius: 1.05,
          stops: [0.55, 1.0],
          colors: [Colors.transparent, Colors.black45],
        ).createShader(full));
}

/// Widget-side bevel: vertical gradient (light top, dark bottom) + soft
/// drop shadow. The border is deliberately UNIFORM: Flutter asserts if a
/// non-uniform Border (light top / dark bottom edges) is combined with a
/// borderRadius, so the two-tone edge is carried by the gradient, not the
/// border. Wraps a button whose own background is transparent; the wrapper
/// supplies the colour.
BoxDecoration glossyDecoration(Color base, double radius) => BoxDecoration(
      borderRadius: BorderRadius.circular(radius),
      gradient: LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [shadeColor(base, 0.28), base, shadeColor(base, -0.28)]),
      border: Border.all(color: Colors.white.withOpacity(0.25), width: 1),
      boxShadow: const [
        BoxShadow(color: Colors.black54, offset: Offset(0, 4), blurRadius: 8),
      ],
    );
